edits.sketch:
// legibleInkFor answers "can this colour be READ on these grounds", which is
// the inverse of pickInkOn's "what can be read ON this fill". It returns
// srcHex unchanged when it already clears minRatio against EVERY ground,
// otherwise the first palette colour that does, otherwise the achromatic
// extreme with the best worst-case.
//
// grounds is a SLICE, not a colour, and that is deliberate. A component may
// place one ink on the page and on a card — dartsonline does exactly that.
// One variable can only be right for two grounds if it is right for the worse
// of them. If a later edit simplifies this to a single ground, the fix
// silently becomes a half-fix: correct on whichever surface the reviewer
// happens to open.
func legibleInkFor(srcHex string, grounds []string, palette map[string]string, minRatio float64) (hex, source string) {
	clearsAll := func(candidate string) bool {
		seen := false
		for _, g := range grounds {
			if g == "" {
				continue
			}
			ratio, err := wcagContrastRatio(candidate, g)
			if err != nil || ratio < minRatio {
				return false
			}
			seen = true
		}
		return seen // no usable ground => not a pass; caller must not emit
	}
	if srcHex != "" && clearsAll(srcHex) {
		return srcHex, "source:unchanged"
	}
	for _, key := range []string{"text", "accent", "text_muted", "secondary", "primary"} {
		if v, ok := palette[key]; ok && v != "" && v != srcHex && clearsAll(v) {
			return v, "palette:" + key
		}
	}
	if worstRatioAgainst("#ffffff", grounds) >= worstRatioAgainst("#000000", grounds) {
		return "#ffffff", "fallback:white"
	}
	return "#000000", "fallback:black"
}

// worstRatioAgainst returns the LOWEST contrast ratio candidate achieves over
// grounds — the only figure that matters when one value must serve them all.
// Returns 0 when no ground is measurable, so an unmeasurable case can never
// win a comparison.
func worstRatioAgainst(candidate string, grounds []string) float64 {
	worst := 0.0
	first := true
	for _, g := range grounds {
		if g == "" {
			continue
		}
		ratio, err := wcagContrastRatio(candidate, g)
		if err != nil {
			continue
		}
		if first || ratio < worst {
			worst, first = ratio, false
		}
	}
	return worst
}

// buildLegibleInkDefaults returns a renderer-owned :root block defining the
// ink companions a component can opt into. "" when there is nothing to add.
//
// TWO DIRECTIONS, and conflating them was the round-1 defect:
//   --color-<x>-text  the ink that goes ON an <x> fill. Already derived by
//                     darkSchemeDerivations; `accent_text` has existed since
//                     2026-07-27 and 0 of 18 layouts declare it, so it has
//                     never reached one stylesheet. Emitting it here is what
//                     turns that dead derivation live.
//   --color-<x>-ink   <x> ITSELF, made legible as an ink on the page. New.
//                     Nothing in the platform computes this.
// finetuning's .csg-cta-btn needs the first (white on an accent fill, 3.01).
// gaswholesalers' `a {}` needs the second (accent on white, 2.22). A plan with
// only one of them fixes one site and reads as if it fixed both.
//
// SCHEME-INDEPENDENT, unlike fillDarkSchemeSpecialisedSlots. That function is
// dark-only because a LIGHT LITERAL is only wrong on a dark site. "This ink is
// illegible on this ground" is true or false regardless of scheme, and two of
// the three accent-direction sites are light (gaswholesalers #F4F1EB,
// finetuning #F5F3EF), so a dark-only guard cannot reach them.
func buildLegibleInkDefaults(css string, palette map[string]string, logger *zap.Logger) string {
	bg := lookupOrFallback(palette, "background", "")
	if bg == "" {
		return "" // nothing to measure against; stay silent rather than guess
	}
	surface := lookupOrFallback(palette, "surface", "")
	pageGrounds := []string{bg, surface} // an ink lands on the page or on a card

	wanted := []struct {
		name, src string
		grounds   []string
	}{
		{"--color-primary-ink", palette["primary"], pageGrounds},
		{"--color-accent-ink", palette["accent"], pageGrounds},
		{"--color-accent-text", palette["text"], []string{palette["accent"]}},
	}

	var b strings.Builder
	var substituted, unchanged []string
	for _, w := range wanted {
		if w.src == "" || strings.Contains(css, w.name+":") {
			continue // undeterminable, or the stylesheet already has an opinion
		}
		hex, src := legibleInkFor(w.src, w.grounds, palette, inkMinContrast)
		b.WriteString("  " + w.name + ": " + hex + ";\n")
		if src == "source:unchanged" {
			unchanged = append(unchanged, w.name)
		} else {
			substituted = append(substituted, w.name+"<-"+src)
		}
	}
	if b.Len() == 0 {
		return ""
	}
	// A substituted value and a left-alone one are indistinguishable in the
	// output CSS. That indistinguishability is the property that let the
	// original defect hide, so both are logged by name.
	sort.Strings(substituted)
	sort.Strings(unchanged)
	logger.Info("buildLegibleInkDefaults: emitted legible-ink companions a component can opt into",
		zap.Strings("substituted", substituted),
		zap.Strings("already_legible_left_as_is", unchanged))
	return "\n\n/* renderer-owned legible-ink companions. Opt in with\n" +
		"   var(--color-primary-ink, var(--color-primary)) — never bare. */\n:root {\n" +
		b.String() + "}\n"
}

